pub fn score_bin(item_size: u32, bin_residual: u32, _bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize open bins
    score -= open_bins_count as f64 * 0.15;

    // Reward small bin residuals
    if bin_residual < 10 {
        score += (10 - bin_residual) as f64;
    }

    // Time index penalty outside of 20-80%
    let time_index = step_index as f64 / total_items as f64;
    if time_index < 0.2 || time_index > 0.8 {
        score -= (time_index.min(1.0) - 0.5).abs() * open_bins_count as f64 * 1.2;
    }

    // Reward fitting bins
    if fitting_bins_count > 0 {
        score += (fitting_bins_count * 3) as f64;
    }

    // Penalize small post-residuals with one open bin
    if post_residual < 35 && open_bins_count == 1 {
        score -= post_residual as f64 / 12.0;
    }

    // Reward high mean residuals
    if mean_residual > 55.0 {
        score += (mean_residual - 55.0) / 12.0;
    }

    // Penalize large next items with one open bin
    if next_item_size > 80 && open_bins_count == 1 {
        score -= next_item_size as f64 / 15.0;
    }

    // Reward small item sizes with small post-residuals
    if item_size < 25 && post_residual < 55 {
        score += (55 - post_residual) as f64;
    }

    // Combine scores with different weights
    let score = score * 0.75 + ((post_residual as f64) as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let stream_progress = (step_index as f64 / total_items as f64).powf(1.5);
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let item_fit_factor = if next_item_size <= bin_residual { 1.0 } else { 0.2 };
    let lookahead_score = (fitting_bins_count as f64).ln() * mean_residual;
    let score = -stream_progress * residual_ratio.powi(3) + 0.5 * stream_progress + item_fit_factor * (1.0 / open_bins_count as f64) + lookahead_score;
    score
}

